    // Show white overlay + spinner to hide old panel during loading
    function showEarlyLoader() {
        if (!document.getElementById('idm-early-hide')) {
            const hideStyle = document.createElement('style');
            hideStyle.id = 'idm-early-hide';
            hideStyle.textContent = `
                iframe[title="Old Panel Page"], #oldPanelPage {
                    visibility: hidden !important;
                    height: 0 !important;
                    overflow: hidden !important;
                }
                .mobile-rel > .container, #pageContent {
                    visibility: hidden !important;
                    height: 0 !important;
                    overflow: hidden !important;
                }
                main > *:not(header):not(footer):not(nav) {
                    visibility: hidden !important;
                    height: 0 !important;
                    overflow: hidden !important;
                }
                main .flex-1 > *:not(#idm-app) {
                    display: none !important;
                }
                #idm-early-loader {
                    position: fixed;
                    top: 0; left: 0; right: 0; bottom: 0;
                    z-index: 99999;
                    display: flex;
                    flex-direction: column;
                    align-items: center;
                    justify-content: center;
                    gap: 12px;
                    background: #fff;
                    font-family: 'Google Sans', Roboto, Arial, sans-serif;
                    color: #5f6368;
                    font-size: 13px;
                }
                #idm-early-loader .idm-early-spinner {
                    width: 32px; height: 32px;
                    border: 3px solid #dadce0;
                    border-top-color: #1a73e8;
                    border-radius: 50%;
                    animation: idm-spin 0.8s linear infinite;
                }
                @keyframes idm-spin { to { transform: rotate(360deg); } }
            `;
            document.head.appendChild(hideStyle);
        }
        if (!document.getElementById('idm-early-loader')) {
            const loader = document.createElement('div');
            loader.id = 'idm-early-loader';
            loader.innerHTML = '<div class="idm-early-spinner"></div><span>Ładowanie menu...</span>';
            (document.body || document.documentElement).appendChild(loader);
        }
    }

    // Preload fonts & show overlay on initial load
    const isMenuTreePage = /[?&]action=menuTree/.test(location.search) || /\/panel\/navigation\.php/.test(location.pathname);
    if (USE_NEW_UI && isMenuTreePage) {
        const injectEarlyAssets = () => {
            const head = document.head;
            if (!head) return false;
            if (document.querySelector('#idm-font-preload')) return true;

            showEarlyLoader();

            const preconnect = document.createElement('link');
            preconnect.rel = 'preconnect';
            preconnect.href = 'https://fonts.googleapis.com';
            head.appendChild(preconnect);

            const preconnect2 = document.createElement('link');
            preconnect2.rel = 'preconnect';
            preconnect2.href = 'https://fonts.gstatic.com';
            preconnect2.crossOrigin = '';
            head.appendChild(preconnect2);

            const fontLink = document.createElement('link');
            fontLink.id = 'idm-font-preload';
            fontLink.rel = 'stylesheet';
            fontLink.href = 'https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@20..48,100..700,0..1,-50..200&display=swap';
            head.appendChild(fontLink);
            return true;
        };
        if (!injectEarlyAssets()) {
            const waitForHead = setInterval(() => {
                if (injectEarlyAssets()) clearInterval(waitForHead);
            }, 10);
        }
    }

    // =========================================================================
    // HELPERS
    // =========================================================================

    function getIframeDoc() {
        const iframe = document.querySelector('iframe[title="Old Panel Page"]');
        if (iframe) return iframe.contentDocument;
        if (document.getElementById('block_0')) return document;
        return null;
    }

    function sleep(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    function getUrlParams() {
        const params = new URLSearchParams(window.location.search);
        return {
            shop: params.get('shop') || '1',
            tree: params.get('tree') || '1',
            lang: params.get('lang') || 'pol',
        };
    }

    function detectAvailableLanguages(iframeDoc) {
        const currentLang = getUrlParams().lang;
        const languages = [];
        // Current language — derive label from page or use code
        const currentLabel = currentLang.toUpperCase();
        languages.push({ code: currentLang, label: currentLabel });
        // Look for language switch links in the iframe
        if (iframeDoc) {
            const links = iframeDoc.querySelectorAll('a[href*="action=menuTree"]');
            for (const link of links) {
                const href = link.getAttribute('href') || '';
                const langMatch = href.match(/[?&]lang=([a-z]{3})/);
                if (langMatch) {
                    const code = langMatch[1];
                    if (!languages.find(l => l.code === code)) {
                        const label = link.textContent.trim() || code.toUpperCase();
                        languages.push({ code, label });
                    }
                }
            }
        }
        return languages;
    }

    async function ajaxPost(params, options) {
        const body = new URLSearchParams(params).toString();
        const fetchOpts = {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            credentials: 'same-origin',
            body,
        };
        // Optional timeout via AbortController
        let controller;
        if (options && options.timeout) {
            controller = new AbortController();
            fetchOpts.signal = controller.signal;
            setTimeout(() => controller.abort(), options.timeout);
        }
        const resp = await fetch('/panel/ajax/navigation.php', fetchOpts);
        if (!resp.ok) {
            throw new Error('HTTP ' + resp.status + ' ' + resp.statusText);
        }
        const text = await resp.text();
        try {
            return JSON.parse(text);
        } catch {
            if (text.trimStart().startsWith('<')) {
                throw new Error('Sesja wygasła — odśwież stronę i zaloguj się ponownie');
            }
            throw new Error('Nieprawidłowa odpowiedź serwera');
        }
    }

    // =========================================================================
    // LLM API (via unsafeWindow.__tmLLM — loader exposes direct functions)
    // =========================================================================

    function callLLM(messages, model) {
        return new Promise(function (resolve, reject) {
            if (!window.__tmLLM || typeof window.__tmLLM.call !== 'function') {
                reject(new Error('Loader nie jest aktywny — odśwież stronę'));
                return;
            }

            var provider = getActiveProvider();
            var providerConfig = getProviderConfig(provider);
            var apiKey = getLLMApiKey(provider);

            if (!apiKey) {
                reject(new Error('Brak klucza API — ustaw go w zakładce Ustawienia'));
                return;
            }

            var resolvedModel = model || getLLMModel(provider);

            // Build headers
            var headers = { 'Content-Type': 'application/json' };
            headers[providerConfig.authHeader] = providerConfig.authPrefix + apiKey;
            if (providerConfig.extraHeaders) {
                var extra = providerConfig.extraHeaders;
                for (var hk in extra) { if (extra.hasOwnProperty(hk)) headers[hk] = extra[hk]; }
            }

            // Build payload — Anthropic needs different format
            var payload;
            if (providerConfig.transformRequest === 'anthropic') {
                var systemMsg = null;
                var userMessages = [];
                for (var i = 0; i < messages.length; i++) {
                    if (messages[i].role === 'system') systemMsg = messages[i].content;
                    else userMessages.push(messages[i]);
                }
                payload = { model: resolvedModel, messages: userMessages, max_tokens: 4096, temperature: 0.3 };
                if (systemMsg) payload.system = systemMsg;
            } else {
                payload = { model: resolvedModel, messages: messages, temperature: 0.3, max_tokens: 4096 };
            }

            var payloadJson = JSON.stringify(payload);
            var headersJson = JSON.stringify(headers);

            window.__tmLLMResult = null;
            window.__tmLLM.call(payloadJson, providerConfig.endpoint, headersJson);

            // Poll for result (no cross-context callbacks needed)
            var poll = setInterval(function () {
                if (window.__tmLLMResult !== null) {
                    clearInterval(poll);
                    clearTimeout(timeout);
                    try {
                        var resp = JSON.parse(window.__tmLLMResult);
                        window.__tmLLMResult = null;
                        if (resp.error === 'NO_KEY') reject(new Error('Brak klucza API — ustaw go w zakładce Ustawienia'));
                        else if (resp.error) reject(new Error(resp.error));
                        else {
                            var result = resp.result;
                            // Normalize Anthropic response to OpenAI format
                            if (providerConfig.transformResponse === 'anthropic' && result.content && !result.choices) {
                                result = {
                                    choices: [{ message: { content: (result.content[0] && result.content[0].text) || '' } }],
                                };
                            }
                            resolve(result);
                        }
                    } catch (e) { reject(e); }
                }
            }, 100);
            var timeout = setTimeout(function () {
                clearInterval(poll);
                reject(new Error('Timeout — brak odpowiedzi z API (120s)'));
            }, 120000);
        });
    }

