    function getActiveProvider() {
        try { return localStorage.getItem('tm_llm_provider') || 'nvidia'; } catch (_) { return 'nvidia'; }
    }
    function saveActiveProvider(providerId) {
        try { localStorage.setItem('tm_llm_provider', providerId); } catch (_) {}
        if (window.__tmLLM && typeof window.__tmLLM.setProvider === 'function') {
            try { window.__tmLLM.setProvider(providerId); } catch (_) {}
        }
    }
    function getProviderConfig(providerId) {
        return LLM_PROVIDERS.find(p => p.id === (providerId || getActiveProvider())) || LLM_PROVIDERS[0];
    }

    function saveLLMApiKey(key, provider) {
        const p = provider || getActiveProvider();
        const storageKey = 'llmApiKey_' + p;
        if (window.__tmLLM && typeof window.__tmLLM.setKey === 'function') {
            window.__tmLLM.setKey(storageKey, key);
        }
        try { localStorage.setItem('tm_' + storageKey, key.trim()); } catch (_) {}
    }

    function getLLMApiKey(provider) {
        const p = provider || getActiveProvider();
        const storageKey = 'llmApiKey_' + p;
        if (window.__tmLLM && typeof window.__tmLLM.getKey === 'function') {
            try { return window.__tmLLM.getKey(storageKey) || ''; } catch (_) {}
        }
        try { return localStorage.getItem('tm_' + storageKey) || ''; } catch (_) { return ''; }
    }

    function saveLLMModel(modelId, provider) {
        const p = provider || getActiveProvider();
        try { localStorage.setItem('tm_llm_model_' + p, modelId); } catch (_) {}
    }
    function getLLMModel(provider) {
        const p = provider || getActiveProvider();
        const cfg = getProviderConfig(p);
        try { return localStorage.getItem('tm_llm_model_' + p) || cfg.defaultModel; } catch (_) { return cfg.defaultModel; }
    }

    function slugify(text) {
        const diacritics = {'ą':'a','ć':'c','ę':'e','ł':'l','ń':'n','ó':'o','ś':'s','ź':'z','ż':'z',
                            'Ą':'a','Ć':'c','Ę':'e','Ł':'l','Ń':'n','Ó':'o','Ś':'s','Ź':'z','Ż':'z'};
        return text.replace(/[ąćęłńóśźżĄĆĘŁŃÓŚŹŻ]/g, c => diacritics[c] || c)
            .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
            .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
    }

    function pathToSlug(parts) {
        return parts.map(p => slugify(p)).filter(Boolean).join('/');
    }

    async function translateNodeFields(nodeId, parentId, sourceLang, targetLang, fields, progressCb, nodeName) {
        // 1. Pobierz dane źródłowe
        progressCb('Pobieranie danych źródłowych...');
        const needDesc = fields.desc || fields.desc_bottom;
        const needSeo = fields.meta_title || fields.meta_description || fields.meta_keywords || fields.own_url;
        const [sourceResp, sourceDesc] = await Promise.all([
            (fields.name || fields.headline || needSeo) ? getNodeData(nodeId, sourceLang) : Promise.resolve(null),
            needDesc ? getNodeDesc(parentId, nodeId, sourceLang) : Promise.resolve(null),
        ]);
        const sourceData = sourceResp?.data || sourceResp || {};

        // 2. Zbuduj obiekt do tłumaczenia
        const toTranslate = {};
        // getNode returns empty name — use nodeName from DOM (it's language-specific for source lang)
        if (fields.name && (sourceData.name || nodeName)) toTranslate.name = sourceData.name || nodeName;
        if (fields.headline && sourceData.headline_name) toTranslate.headline = sourceData.headline_name;
        if (fields.desc && sourceDesc?.desc) toTranslate.desc = sourceDesc.desc;
        if (fields.desc_bottom && sourceDesc?.desc_bottom) toTranslate.desc_bottom = sourceDesc.desc_bottom;
        if (fields.meta_title && sourceData.meta_title) toTranslate.meta_title = sourceData.meta_title;
        if (fields.meta_description && sourceData.meta_description) toTranslate.meta_description = sourceData.meta_description;
        if (fields.meta_keywords && sourceData.meta_keywords) toTranslate.meta_keywords = sourceData.meta_keywords;
        if (fields.own_url && sourceData.own_url) toTranslate.own_url = sourceData.own_url;

        if (Object.keys(toTranslate).length === 0) throw new Error('Brak danych źródłowych do tłumaczenia');

        // 3. Tłumacz przez LLM
        const sourceName = LANG_META[sourceLang]?.name || sourceLang;
        const targetName = LANG_META[targetLang]?.name || targetLang;
        progressCb(`Tłumaczenie (${sourceName} → ${targetName})...`);

        let prompt = `Translate the following JSON values from ${sourceName} to ${targetName}.
Keep HTML tags intact. Return ONLY a valid JSON object with the same keys and translated values.
Do not add any explanation or markdown formatting.`;
        if (toTranslate.own_url) {
            prompt += `\nFor "own_url": translate the meaning and create a clean SEO-friendly URL slug. Technical constraints: lowercase, hyphens between words, no diacritics (transliterate ą→a, ę→e, ć→c, ó→o, ł→l, ś→s, ż→z, ź→z, ń→n), no special chars, no leading/trailing slashes.`;
        }
        prompt += `\n\n${JSON.stringify(toTranslate, null, 2)}`;

        const resp = await callLLM([{ role: 'user', content: prompt }]);
        const content = resp.choices?.[0]?.message?.content || '';
        const jsonMatch = content.match(/\{[\s\S]*\}/);
        if (!jsonMatch) throw new Error('LLM nie zwrócił poprawnego JSON');
        const translated = JSON.parse(jsonMatch[0]);

        return { source: toTranslate, translated };
    }

    async function generateNodeContent(nodeId, parentId, targetLang, fields, extraInstructions, nodePath, progressCb, nodeName) {
        progressCb('Pobieranie kontekstu...');
        const nodeResp = await getNodeData(nodeId, targetLang);
        const nodeData = nodeResp?.data || nodeResp || {};
        const resolvedName = nodeData.name || nodeName || '';

        const targetName = LANG_META[targetLang]?.name || targetLang;
        const fieldsToGenerate = [];
        if (fields.name) fieldsToGenerate.push('"name": category name (short, concise)');
        if (fields.headline) fieldsToGenerate.push('"headline": headline/display name for the category');
        if (fields.desc) fieldsToGenerate.push('"desc": top HTML description (2-4 paragraphs with <p>, <strong>, <ul>/<li> tags)');
        if (fields.desc_bottom) fieldsToGenerate.push('"desc_bottom": bottom HTML description (1-2 paragraphs, can include <p>, <strong> tags)');
        if (fields.meta_title) fieldsToGenerate.push('"meta_title": SEO title (max 60 chars)');
        if (fields.meta_description) fieldsToGenerate.push('"meta_description": SEO description (max 160 chars)');
        if (fields.meta_keywords) fieldsToGenerate.push('"meta_keywords": comma-separated keywords');
        if (fields.own_url) fieldsToGenerate.push('"own_url": SEO-friendly URL slug for this category');

        if (fieldsToGenerate.length === 0) throw new Error('Nie wybrano pól do generowania');

        progressCb('Generowanie treści...');

        const pathStr = (nodePath && nodePath.length > 1) ? nodePath.join(' > ') : resolvedName;

        const messages = [];

        messages.push({ role: 'system', content: `You are an SEO content writer for an e-commerce store. You generate JSON with requested fields. Return ONLY a valid JSON object, no markdown, no explanation, no wrapping.` });

        let userPrompt = `Generate content in ${targetName} for this menu category: "${resolvedName}".
Full category path: ${pathStr}

Generate the following fields as a JSON object:
${fieldsToGenerate.join('\n')}

Rules:
- All content must be about "${resolvedName}" (path: ${pathStr})
- Write naturally, avoid keyword stuffing
- For HTML fields (desc, desc_bottom): use proper HTML tags (<p>, <strong>, <ul>/<li>, <h2>/<h3>). Write engaging, informative e-commerce category descriptions
- For name/headline: keep them short and descriptive
- For own_url: create a clean, SEO-optimized URL slug. Technical constraints: lowercase, hyphens between words, no diacritics (transliterate ą→a, ę→e, ć→c, ó→o, ł→l, ś→s, ż→z, ź→z, ń→n), no special chars, no leading/trailing slashes`;

        if (extraInstructions) {
            userPrompt += `\n\nCRITICAL — MANDATORY USER INSTRUCTIONS (these override ALL rules above, follow them exactly):\n${extraInstructions}`;
        }

        messages.push({ role: 'user', content: userPrompt });

        const resp = await callLLM(messages);
        const content = resp.choices?.[0]?.message?.content || '';
        const jsonMatch = content.match(/\{[\s\S]*\}/);
        if (!jsonMatch) throw new Error('LLM nie zwrócił poprawnego JSON');
        return JSON.parse(jsonMatch[0]);
    }

    async function improveNodeContent(nodeId, parentId, lang, fields, extraInstructions, progressCb, nodeName) {
        progressCb('Pobieranie obecnych treści...');
        const needDesc = fields.desc || fields.desc_bottom;
        const needNode = fields.name || fields.headline || fields.meta_title || fields.meta_description || fields.meta_keywords || fields.own_url;
        const [nodeResp, descData] = await Promise.all([
            needNode ? getNodeData(nodeId, lang) : Promise.resolve(null),
            needDesc ? getNodeDesc(parentId, nodeId, lang) : Promise.resolve(null),
        ]);
        const nodeData = nodeResp?.data || nodeResp || {};

        const toImprove = {};
        if (fields.name && (nodeData.name || nodeName)) toImprove.name = nodeData.name || nodeName;
        if (fields.headline && nodeData.headline_name) toImprove.headline = nodeData.headline_name;
        if (fields.desc && descData?.desc) toImprove.desc = descData.desc;
        if (fields.desc_bottom && descData?.desc_bottom) toImprove.desc_bottom = descData.desc_bottom;
        if (fields.meta_title && nodeData.meta_title) toImprove.meta_title = nodeData.meta_title;
        if (fields.meta_description && nodeData.meta_description) toImprove.meta_description = nodeData.meta_description;
        if (fields.meta_keywords && nodeData.meta_keywords) toImprove.meta_keywords = nodeData.meta_keywords;
        if (fields.own_url && nodeData.own_url) toImprove.own_url = nodeData.own_url;

        if (Object.keys(toImprove).length === 0) throw new Error('Brak treści do poprawy (pola są puste)');

        const langName = LANG_META[lang]?.name || lang;
        const resolvedName = nodeData.name || nodeName || '';
        progressCb('Ulepszanie treści...');

        const fieldDescs = [];
        if (toImprove.name) fieldDescs.push('"name": category name (short, concise)');
        if (toImprove.headline) fieldDescs.push('"headline": headline/display name');
        if (toImprove.desc) fieldDescs.push('"desc": top description (HTML)');
        if (toImprove.desc_bottom) fieldDescs.push('"desc_bottom": bottom description (HTML)');
        if (toImprove.meta_title) fieldDescs.push('"meta_title": SEO title (max 60 chars)');
        if (toImprove.meta_description) fieldDescs.push('"meta_description": SEO description (max 160 chars)');
        if (toImprove.meta_keywords) fieldDescs.push('"meta_keywords": comma-separated keywords');
        if (toImprove.own_url) fieldDescs.push('"own_url": SEO-friendly URL slug');

        let prompt = `You are an expert e-commerce content editor. Improve the following content for the menu category "${resolvedName}" in ${langName}.

Current content:
${JSON.stringify(toImprove, null, 2)}

Fields to improve:
${fieldDescs.join('\n')}

Rules:
- Keep the same language (${langName})
- Improve readability, SEO quality, and engagement
- Fix grammar and spelling errors
- Make HTML descriptions more structured (use <p>, <strong>, <ul>/<li> where appropriate)
- Keep the same general meaning but make it more professional and compelling
- For own_url: create a clean, SEO-optimized URL slug. Technical constraints: lowercase, hyphens between words, no diacritics, no special chars, no leading/trailing slashes
- Return ONLY a valid JSON object with the same keys and improved values
- Do not add any explanation or markdown formatting`;

        if (extraInstructions) prompt += `\n\nCRITICAL — User's additional instructions (MUST override default rules above):\n${extraInstructions}`;

        const resp = await callLLM([{ role: 'user', content: prompt }]);
        const content = resp.choices?.[0]?.message?.content || '';
        const jsonMatch = content.match(/\{[\s\S]*\}/);
        if (!jsonMatch) throw new Error('LLM nie zwrócił poprawnego JSON');
        return { source: toImprove, improved: JSON.parse(jsonMatch[0]) };
    }

    async function saveTranslatedFields(nodeId, parentId, targetLang, translated, progressCb) {
        // 1. Zapis name/headline → saveNodeShopData
        if (translated.name || translated.headline) {
            progressCb('Zapisywanie nazwy/nagłówka...');
            const targetResp = await getNodeData(nodeId, targetLang);
            const targetData = targetResp?.data || targetResp || {};
            const overrides = {};
            if (translated.name) overrides.name = translated.name;
            if (translated.headline) {
                overrides.text_d_headline_name = 'o';
                overrides.headline_name = translated.headline;
            }
            await saveNodeShopData(parentId, nodeId, targetData, overrides, targetLang);
        }

        // 2. Zapis desc/desc_bottom → saveNodeDesc
        if (translated.desc !== undefined || translated.desc_bottom !== undefined) {
            progressCb('Zapisywanie opisów...');
            const descResp = await getNodeDesc(parentId, nodeId, targetLang);
            const currentDesc = descResp?.desc || '';
            const currentDescBottom = descResp?.desc_bottom || '';
            await saveNodeDesc(parentId, nodeId,
                translated.desc ?? currentDesc,
                translated.desc_bottom ?? currentDescBottom,
                targetLang);
        }

        // 3. Zapis meta + own_url → saveNodeSEOData
        if (translated.meta_title !== undefined || translated.meta_description !== undefined || translated.meta_keywords !== undefined || translated.own_url !== undefined) {
            progressCb('Zapisywanie meta tagów...');
            const seoResp = await getNodeData(nodeId, targetLang);
            const seoData = seoResp?.data || seoResp || {};
            const seoOverrides = {};
            if (translated.meta_title !== undefined) { seoOverrides.meta_title = translated.meta_title; seoOverrides.meta_default = 'n'; }
            if (translated.meta_description !== undefined) { seoOverrides.meta_desc = translated.meta_description; seoOverrides.meta_default = 'n'; }
            if (translated.meta_keywords !== undefined) seoOverrides.meta_keywords = translated.meta_keywords;
            if (translated.own_url !== undefined) { seoOverrides.own_url_default = 'n'; seoOverrides.own_url = translated.own_url; }
            await saveNodeSEOData(nodeId, seoData, seoOverrides, targetLang);
        }

        progressCb('Zapisano!');
    }

    async function fetchImageAsBase64(url) {
        if (!url) return null;
        try {
            const resp = await fetch(url, { credentials: 'same-origin' });
            if (!resp.ok) return null;
            const blob = await resp.blob();
            return new Promise(resolve => {
                const reader = new FileReader();
                reader.onloadend = () => resolve(reader.result);
                reader.readAsDataURL(blob);
            });
        } catch (e) {
            return null;
        }
    }

    /**
     * Returns all collapsed plusik elements (class showChildren, visible, with hidden block).
     */
    function getCollapsedPlusiks(iframeDoc) {
        const result = [];
        const plusiks = iframeDoc.querySelectorAll('.plusik.showChildren');
        for (const plusik of plusiks) {
            if (plusik.style.display === 'none') continue;
            const li = plusik.closest('.menu_li_item');
            if (!li) continue;
            const id = li.id.replace('m', '');
            const block = iframeDoc.querySelector('#block_' + id);
            if (block && block.style.display === 'none') {
                result.push({ plusik, id, block });
            }
        }
        return result;
    }

    /**
     * Returns all expanded plusik elements (class hideChildren), sorted deepest-first.
     */
    function getExpandedPlusiks(iframeDoc) {
        const result = [];
        const plusiks = iframeDoc.querySelectorAll('.plusik.hideChildren');
        for (const plusik of plusiks) {
            const li = plusik.closest('.menu_li_item');
            if (!li) continue;
            let depth = 0;
            let el = li.parentElement;
            while (el) {
                if (el.classList && el.classList.contains('menu_ul')) depth++;
                el = el.parentElement;
            }
            result.push({ plusik, id: li.id, depth });
        }
        result.sort((a, b) => b.depth - a.depth);
        return result;
    }

    // =========================================================================
    // PHASE 1: EXPAND / COLLAPSE ALL
    // =========================================================================

    let expandAbortController = null;

    /**
     * Checks if a menu item (li) has a collapsed plusik that can be expanded.
     * Returns the plusik element or null.
     */
    function getCollapsedPlusikForItem(li) {
        const id = li.id.replace('m', '');
        const plusik = li.querySelector('#show_' + id + '.plusik.showChildren');
        if (!plusik || plusik.style.display === 'none') return null;
        const block = li.querySelector('#block_' + id);
        if (block && block.style.display === 'none') return plusik;
        return null;
    }

    /**
     * Waits until children are actually loaded inside the block element.
     * Uses MutationObserver for instant detection with polling fallback.
     */
    async function waitForChildrenLoaded(iframeDoc, id, signal) {
        // Fast path: children already loaded
        const block = iframeDoc.querySelector('#block_' + id);
        if (block && block.style.display !== 'none' && block.querySelector('.menu_li_item')) {
            return;
        }

        return new Promise((resolve) => {
            const timeout = setTimeout(() => {
                if (observer) observer.disconnect();
                if (pollTimer) clearInterval(pollTimer);
                resolve();
            }, CONFIG.EXPAND_POLL_TIMEOUT_MS);

            const cleanup = () => {
                clearTimeout(timeout);
                if (observer) observer.disconnect();
                if (pollTimer) clearInterval(pollTimer);
                resolve();
            };

            // Abort support
            if (signal.aborted) { clearTimeout(timeout); resolve(); return; }
            const onAbort = () => cleanup();
            signal.addEventListener('abort', onAbort, { once: true });

            const checkLoaded = () => {
                const b = iframeDoc.querySelector('#block_' + id);
                if (b && b.style.display !== 'none' && b.querySelector('.menu_li_item')) {
                    signal.removeEventListener('abort', onAbort);
                    cleanup();
                    return true;
                }
                return false;
            };

            // MutationObserver: watch for child insertion
            let observer = null;
            const targetBlock = iframeDoc.querySelector('#block_' + id);
            if (targetBlock) {
                observer = new MutationObserver(() => { checkLoaded(); });
                observer.observe(targetBlock, { childList: true, subtree: true });
            }

            // Polling fallback (block might not exist yet, or observer misses attribute changes)
            const pollTimer = setInterval(() => { checkLoaded(); }, CONFIG.EXPAND_POLL_INTERVAL_MS);
        });
    }

    async function expandAllBFS(iframeDoc, statusCallback) {
        expandAbortController = new AbortController();
        const signal = expandAbortController.signal;
        const state = { total: 0, topLevel: 0, subLevel: 0 };
        const CONCURRENCY = CONFIG.EXPAND_CONCURRENCY;

        const rootBlock = iframeDoc.querySelector('#block_0');
        if (!rootBlock) { expandAbortController = null; return state; }

        let currentLevel = [...rootBlock.querySelectorAll(':scope > .menu_li_item')];
        let depth = 0;

        while (currentLevel.length > 0 && !signal.aborted) {
            // Collect all collapsed plusiks at this level
            const toExpand = [];
            for (const li of currentLevel) {
                const plusik = getCollapsedPlusikForItem(li);
                if (plusik) toExpand.push({ li, plusik, id: li.id.replace('m', '') });
            }

            // Expand in parallel batches
            for (let i = 0; i < toExpand.length; i += CONCURRENCY) {
                if (signal.aborted) break;
                const batch = toExpand.slice(i, i + CONCURRENCY);

                for (const { plusik } of batch) plusik.click();
                state.total += batch.length;
                if (depth === 0) state.topLevel += batch.length;
                else state.subLevel += batch.length;
                statusCallback(`Rozwijam... (${state.total} rozwiniętych, poziom ${depth})`);

                await Promise.all(batch.map(({ id }) =>
                    waitForChildrenLoaded(iframeDoc, id, signal)
                ));
            }

            // Collect children for next level
            const nextLevel = [];
            for (const li of currentLevel) {
                const id = li.id.replace('m', '');
                const block = iframeDoc.querySelector('#block_' + id);
                if (block && block.style.display !== 'none') {
                    nextLevel.push(...block.querySelectorAll(':scope > .menu_li_item'));
                }
            }
            currentLevel = nextLevel;
            depth++;
        }

        expandAbortController = null;
        return state;
    }

    // Legacy alias for call sites
    const expandAll = expandAllBFS;

    function collapseAll(iframeDoc) {
        // Abort any running expand operation
        if (expandAbortController) {
            expandAbortController.abort();
            expandAbortController = null;
        }

        // Click all expanded (hideChildren) plusiks, deepest first.
        // This uses the panel's native mechanism so internal state stays consistent.
        const expanded = getExpandedPlusiks(iframeDoc);
        for (const { plusik } of expanded) {
            plusik.click();
        }

        return expanded.length;
    }

    // =========================================================================
    // PHASE 2: CHECKBOXES & SELECTION
    // =========================================================================

    const selectedNodes = new Set();
    let selectionCounterEl = null;

    function getNodeId(li) {
        return li.id.replace('m', '');
    }

    function getNodeName(li) {
        const el = li.querySelector('.showoptions');
        return el ? el.textContent.trim() : getNodeId(li);
    }

    function countDepth(li) {
        let depth = 0;
        let el = li.parentElement?.closest('.menu_li_item');
        while (el) { depth++; el = el.parentElement?.closest('.menu_li_item'); }
        return depth;
    }

    function getNodePath(li) {
        const parts = [];
        let current = li;
        while (current) {
            parts.unshift(getNodeName(current));
            current = current.parentElement?.closest('.menu_li_item');
        }
        return parts;
    }

    /**
     * Injects a checkbox into a single menu_li_item if not already present.
     */
    function injectCheckbox(li, iframeDoc) {
        const id = getNodeId(li);
        if (li.querySelector('.tm-checkbox')) return;

        const itemInfo = li.querySelector('.menu_iteminfo');
        if (!itemInfo) return;

        const cb = iframeDoc.createElement('input');
        cb.type = 'checkbox';
        cb.className = 'tm-checkbox';
        cb.dataset.nodeId = id;
        cb.checked = selectedNodes.has(id);

        cb.addEventListener('change', (e) => {
            e.stopPropagation();
            if (cb.checked) {
                selectedNodes.add(id);
            } else {
                selectedNodes.delete(id);
            }
            // Propagate to all children
            const block = iframeDoc.querySelector('#block_' + id);
            if (block) {
                const childItems = block.querySelectorAll('.menu_li_item');
                for (const child of childItems) {
                    const childId = getNodeId(child);
                    if (cb.checked) {
                        selectedNodes.add(childId);
                    } else {
                        selectedNodes.delete(childId);
                    }
                    const childCb = child.querySelector('.tm-checkbox');
                    if (childCb) childCb.checked = cb.checked;
                }
            }
            updateSelectionCounter();
        });

        cb.addEventListener('click', (e) => {
            e.stopPropagation();
        });

        // Insert before plusik (first child of itemInfo)
        itemInfo.insertBefore(cb, itemInfo.firstChild);
    }

    /**
     * Injects checkboxes into all visible menu items.
     */
    function injectAllCheckboxes(iframeDoc) {
        const items = iframeDoc.querySelectorAll('.menu_li_item');
        for (const li of items) {
            injectCheckbox(li, iframeDoc);
        }
    }

    function updateSelectionCounter() {
        if (selectionCounterEl) {
            const count = selectedNodes.size;
            selectionCounterEl.textContent = count > 0
                ? `Zaznaczono: ${count}`
                : '';
        }
    }

    // =========================================================================
    // INLINE NODE NAME EDITING
    // =========================================================================

    let _inlineEditActive = false;

    function startInlineEdit(li, iframeDoc) {
        if (_inlineEditActive) return;
        const nameEl = li.querySelector('.showoptions');
        if (!nameEl) return;

        _inlineEditActive = true;
        const originalName = nameEl.textContent.trim();
        const nodeId = getNodeId(li);

        // Hide pencil button while editing
        const pencilBtn = li.querySelector('.tm-inline-edit-btn');
        if (pencilBtn) pencilBtn.style.display = 'none';

        // Replace text with input
        const input = iframeDoc.createElement('input');
        input.type = 'text';
        input.className = 'tm-inline-edit-input';
        input.value = originalName;
        input.style.width = Math.max(80, Math.min(400, originalName.length * 8 + 20)) + 'px';

        // Hide original text
        const originalDisplay = nameEl.style.display;
        nameEl.style.display = 'none';
        nameEl.parentElement.insertBefore(input, nameEl.nextSibling);
        input.focus();
        input.select();

        function cancelEdit() {
            input.remove();
            nameEl.style.display = originalDisplay;
            if (pencilBtn) pencilBtn.style.display = '';
            _inlineEditActive = false;
        }

        async function saveEdit() {
            const newName = input.value.trim();
            if (!newName || newName === originalName) {
                cancelEdit();
                return;
            }

            // Show saving state
            input.classList.add('tm-inline-edit-saving');
            input.disabled = true;

            try {
                const parentId = getParentNodeId(iframeDoc, nodeId);
                const nodeData = await getNodeData(nodeId);
                const currentData = nodeData && nodeData.data ? nodeData.data : {};

                await saveNodeShopData(parentId, nodeId, currentData, { name: newName });

                // Update DOM
                nameEl.textContent = newName;
                input.remove();
                nameEl.style.display = originalDisplay;
                if (pencilBtn) pencilBtn.style.display = '';
                _inlineEditActive = false;
            } catch (err) {
                input.classList.remove('tm-inline-edit-saving');
                input.disabled = false;
                input.style.borderColor = '#d93025';
                input.style.boxShadow = '0 0 0 2px rgba(217,48,37,0.25)';
                input.title = 'Błąd zapisu: ' + (err.message || err);
                // Allow retry or cancel
            }
        }

        input.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                saveEdit();
            } else if (e.key === 'Escape') {
                e.preventDefault();
                cancelEdit();
            }
            e.stopPropagation();
        });

        input.addEventListener('blur', () => {
            // Small delay to allow click on other elements
            setTimeout(() => {
                if (_inlineEditActive && document.activeElement !== input && iframeDoc.activeElement !== input) {
                    saveEdit();
                }
            }, 150);
        });

        // Prevent clicks from propagating to tree handlers
        input.addEventListener('click', (e) => e.stopPropagation());
        input.addEventListener('mousedown', (e) => e.stopPropagation());
    }

    function injectInlineEdit(li, iframeDoc) {
        if (li.querySelector('.tm-inline-edit-btn')) return;
        const nameEl = li.querySelector('.showoptions');
        if (!nameEl) return;

        // Pencil icon button
        const btn = iframeDoc.createElement('button');
        btn.className = 'tm-inline-edit-btn';
        btn.title = 'Edytuj nazwę (dwuklik na nazwę)';
        btn.innerHTML = '&#9998;'; // ✎ pencil
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            e.preventDefault();
            startInlineEdit(li, iframeDoc);
        });
        nameEl.insertAdjacentElement('afterend', btn);

        // Double-click on name
        nameEl.addEventListener('dblclick', (e) => {
            e.stopPropagation();
            e.preventDefault();
            startInlineEdit(li, iframeDoc);
        });
    }

    function injectAllInlineEdits(iframeDoc) {
        const items = iframeDoc.querySelectorAll('.menu_li_item');
        for (const li of items) {
            injectInlineEdit(li, iframeDoc);
        }
    }

    function selectAll(iframeDoc) {
        const items = iframeDoc.querySelectorAll('.menu_li_item');
        for (const li of items) {
            const id = getNodeId(li);
            selectedNodes.add(id);
            const cb = li.querySelector('.tm-checkbox');
            if (cb) cb.checked = true;
        }
        updateSelectionCounter();
    }

    function deselectAll(iframeDoc) {
        selectedNodes.clear();
        const cbs = iframeDoc.querySelectorAll('.tm-checkbox');
        for (const cb of cbs) {
            cb.checked = false;
        }
        updateSelectionCounter();
    }

    function selectChildren(li, iframeDoc) {
        const id = getNodeId(li);
        const block = iframeDoc.querySelector('#block_' + id);
        if (!block) return;
        const children = block.querySelectorAll('.menu_li_item');
        for (const child of children) {
            const childId = getNodeId(child);
            selectedNodes.add(childId);
            const cb = child.querySelector('.tm-checkbox');
            if (cb) cb.checked = true;
        }
        updateSelectionCounter();
    }

    function invertSelection(iframeDoc) {
        const items = iframeDoc.querySelectorAll('.menu_li_item');
        for (const li of items) {
            const id = getNodeId(li);
            const cb = li.querySelector('.tm-checkbox');
            if (selectedNodes.has(id)) {
                selectedNodes.delete(id);
                if (cb) cb.checked = false;
            } else {
                selectedNodes.add(id);
                if (cb) cb.checked = true;
            }
        }
        updateSelectionCounter();
    }

