    // --- Auto URL generation from pattern ---
    let _autoUrlTemplateCache = null;

    function slugify(name) {
        // Transliterate Polish chars
        const map = { 'ą':'a','ć':'c','ę':'e','ł':'l','ń':'n','ó':'o','ś':'s','ź':'z','ż':'z',
                       'Ą':'A','Ć':'C','Ę':'E','Ł':'L','Ń':'N','Ó':'O','Ś':'S','Ź':'Z','Ż':'Z' };
        let s = name.replace(/[ąćęłńóśźżĄĆĘŁŃÓŚŹŻ]/g, c => map[c] || c);
        s = s.replace(/[()[\]{}<>!@#$%^&*+=~`'",:;?/\\|]/g, ''); // remove special chars
        s = s.replace(/\s+/g, '-'); // spaces → hyphens
        s = s.replace(/-{2,}/g, '-'); // collapse multiple hyphens
        s = s.replace(/^-|-$/g, ''); // trim hyphens
        return s;
    }

    async function deriveAutoUrlTemplate() {
        if (_autoUrlTemplateCache) return _autoUrlTemplateCache;
        // Find auto-URL nodes from the tree DOM
        const iframeDoc = getIframeDoc();
        if (!iframeDoc) return null;
        const lis = iframeDoc.querySelectorAll('.menu_li_item');
        for (const li of lis) {
            const nid = getNodeId(li);
            if (!nid) continue;
            try {
                const [nodeResp, seoResp] = await Promise.all([
                    getNodeData(nid),
                    getNodeSEOData(nid),
                ]);
                const d = nodeResp && nodeResp.data ? nodeResp.data : null;
                const sd = seoResp && seoResp.data ? seoResp.data : null;
                if (!d || !sd) continue;
                // Must have auto URL (no own_url) and fresh seolink
                if (sd.own_url || d.need_seolink_refresh === 'y') continue;
                const seolink = (d.seolink && d.seolink[0]) || '';
                const name = d.name || d.title_name || '';
                if (!seolink || !name) continue;
                // Extract slug from seolink using name→slug conversion
                const slug = slugify(name);
                const idStr = String(nid);
                // Check if seolink contains the slug and id
                try {
                    const parsed = new URL(seolink);
                    const path = parsed.pathname;
                    const slugIdx = path.indexOf(slug);
                    const idIdx = path.indexOf(idStr, slugIdx > -1 ? slugIdx : 0);
                    if (slugIdx > -1 && idIdx > -1) {
                        const prefix = parsed.origin + path.substring(0, slugIdx);
                        const between = path.substring(slugIdx + slug.length, idIdx);
                        const suffix = path.substring(idIdx + idStr.length);
                        _autoUrlTemplateCache = { prefix, between, suffix, domain: parsed.origin };
                        return _autoUrlTemplateCache;
                    }
                } catch {}
            } catch {}
        }
        return null;
    }

    function generateAutoUrl(template, nodeName, nodeId) {
        if (!template) return '';
        const slug = slugify(nodeName);
        return template.prefix + slug + template.between + nodeId + template.suffix;
    }

    function getParentNodeId(iframeDoc, nodeId) {
        const li = iframeDoc.querySelector('#m' + nodeId);
        if (!li) return '0';
        const parentUl = li.parentElement;
        if (!parentUl || parentUl.id === 'block_0') return '0';
        return parentUl.id.replace('block_', '');
    }

    // Module-level store — set when USE_NEW_UI is active
    let treeStore = null;

    /**
     * Resolves node name and parentId from store (new UI) or DOM (legacy).
     */
    function resolveNodeInfo(nodeId, iframeDoc) {
        if (treeStore) {
            const node = treeStore.nodes.get(nodeId);
            return { name: node ? node.name : nodeId, parentId: node ? node.parentId : '0' };
        }
        const li = iframeDoc ? iframeDoc.querySelector('#m' + nodeId) : null;
        return {
            name: li ? getNodeName(li) : nodeId,
            parentId: getParentNodeId(iframeDoc, nodeId),
        };
    }

    // =========================================================================
    // TREE STORE — state management for new UI
    // =========================================================================

    class TreeStore extends EventTarget {
        constructor() {
            super();
            this.nodes = new Map();     // id → { id, name, parentId, childIds, depth, hasChildren, loaded, productCount }
            this.rootOrder = [];        // ordered IDs of top-level nodes (parentId === '0')
            this.expanded = new Set();
            this.selected = new Set();
            this.loading = new Set();
            this.searchQuery = '';
            this.activeView = null; // { name, nodes: [{id, path}] } or null
        }

        addNode(node) {
            this.nodes.set(node.id, {
                id: node.id,
                name: node.name || '',
                parentId: node.parentId || '0',
                childIds: node.childIds || [],
                depth: node.depth || 0,
                hasChildren: node.hasChildren ?? (node.childIds && node.childIds.length > 0),
                loaded: node.loaded ?? false,
                productCount: node.productCount || 0,
                hidden: node.hidden ?? null, // null=unknown, 'y'=hidden, 'n'=visible
            });
        }

        removeNode(nodeId) {
            const node = this.nodes.get(nodeId);
            if (!node) return;
            // Remove from parent's childIds or rootOrder
            if (node.parentId === '0') {
                this.rootOrder = this.rootOrder.filter(id => id !== nodeId);
            } else {
                const parent = this.nodes.get(node.parentId);
                if (parent) {
                    parent.childIds = parent.childIds.filter(id => id !== nodeId);
                    if (parent.childIds.length === 0) {
                        parent.hasChildren = false;
                        this.expanded.delete(parent.id);
                    }
                }
            }
            // Remove all descendants recursively
            const removeDescendants = (id) => {
                const n = this.nodes.get(id);
                if (!n) return;
                for (const childId of n.childIds) removeDescendants(childId);
                this.nodes.delete(id);
                this.expanded.delete(id);
                this.selected.delete(id);
            };
            removeDescendants(nodeId);
            this.emit('change');
        }

        toggleExpand(nodeId) {
            if (this.expanded.has(nodeId)) {
                this.expanded.delete(nodeId);
                _lastCollapsedId = nodeId;
                _lastExpandedId = null;
            } else {
                this.expanded.add(nodeId);
                _lastExpandedId = nodeId;
                _lastCollapsedId = null;
            }
            this.emit('change');
        }

        setExpanded(nodeId, value) {
            if (value) this.expanded.add(nodeId);
            else this.expanded.delete(nodeId);
        }

        toggleSelect(nodeId, propagate = true) {
            const wasSelected = this.selected.has(nodeId);
            if (wasSelected) {
                this.selected.delete(nodeId);
            } else {
                this.selected.add(nodeId);
            }
            // Propagate to descendants
            if (propagate) {
                const propagateDown = (id) => {
                    const node = this.nodes.get(id);
                    if (!node) return;
                    for (const childId of node.childIds) {
                        if (wasSelected) this.selected.delete(childId);
                        else this.selected.add(childId);
                        propagateDown(childId);
                    }
                };
                propagateDown(nodeId);
            }
            // Sync with global selectedNodes (diff only)
            if (wasSelected) {
                selectedNodes.delete(nodeId);
                if (propagate) {
                    const removeDown = (id) => {
                        const n = this.nodes.get(id);
                        if (!n) return;
                        for (const cid of n.childIds) { selectedNodes.delete(cid); removeDown(cid); }
                    };
                    removeDown(nodeId);
                }
            } else {
                selectedNodes.add(nodeId);
                if (propagate) {
                    const addDown = (id) => {
                        const n = this.nodes.get(id);
                        if (!n) return;
                        for (const cid of n.childIds) { selectedNodes.add(cid); addDown(cid); }
                    };
                    addDown(nodeId);
                }
            }
            this.emit('change');
        }

        selectAll() {
            for (const [id] of this.nodes) this.selected.add(id);
            selectedNodes.clear();
            for (const id of this.selected) selectedNodes.add(id);
            this.emit('change');
        }

        deselectAll() {
            this.selected.clear();
            selectedNodes.clear();
            this.emit('change');
        }

        invertSelection() {
            for (const [id] of this.nodes) {
                if (this.selected.has(id)) this.selected.delete(id);
                else this.selected.add(id);
            }
            selectedNodes.clear();
            for (const id of this.selected) selectedNodes.add(id);
            this.emit('change');
        }

        setLoading(nodeId, value) {
            if (value) this.loading.add(nodeId);
            else this.loading.delete(nodeId);
            this.emit('change');
        }

        getVisibleNodes() {
            const result = [];
            const searchLower = this.searchQuery ? this.searchQuery.toLowerCase() : '';
            const memo = searchLower ? new Map() : null;

            // View filter: resolve node IDs + ancestors
            let viewNodeIds = null;
            let viewAncestorIds = null;
            if (this.activeView) {
                viewNodeIds = resolveViewNodeIds(this, this.activeView);
                viewAncestorIds = getViewAncestorIds(this, viewNodeIds);
            }

            const walk = (parentId, depth) => {
                const children = parentId === '0'
                    ? this.rootOrder.map(id => this.nodes.get(id)).filter(Boolean)
                    : (this.nodes.get(parentId)?.childIds || []).map(id => this.nodes.get(id)).filter(Boolean);
                for (const node of children) {
                    // View filter: skip nodes not in view and not ancestors of view nodes
                    if (viewNodeIds && !viewNodeIds.has(node.id) && !viewAncestorIds.has(node.id)) {
                        continue;
                    }

                    const matchesSearch = !searchLower ||
                        node.name.toLowerCase().includes(searchLower);
                    if (searchLower && !matchesSearch) {
                        const hasMatchingDescendant = this._hasMatchingDescendant(node.id, searchLower, memo);
                        if (!hasMatchingDescendant) continue;
                    }
                    const isViewAncestor = viewNodeIds && !viewNodeIds.has(node.id) && viewAncestorIds.has(node.id);
                    result.push({ ...node, depth, isViewAncestor });
                    if (this.expanded.has(node.id) && node.loaded) {
                        walk(node.id, depth + 1);
                    }
                }
            };
            walk('0', 0);
            return result;
        }

        _hasMatchingDescendant(nodeId, searchLower, memo) {
            if (memo && memo.has(nodeId)) return memo.get(nodeId);
            const node = this.nodes.get(nodeId);
            if (!node) { if (memo) memo.set(nodeId, false); return false; }
            for (const childId of node.childIds) {
                const child = this.nodes.get(childId);
                if (!child) continue;
                if (child.name.toLowerCase().includes(searchLower)) { if (memo) memo.set(nodeId, true); return true; }
                if (this._hasMatchingDescendant(childId, searchLower, memo)) { if (memo) memo.set(nodeId, true); return true; }
            }
            if (memo) memo.set(nodeId, false);
            return false;
        }

        getNodePath(nodeId) {
            const parts = [];
            let current = this.nodes.get(nodeId);
            while (current) {
                parts.unshift(current.name);
                if (current.parentId === '0') break;
                current = this.nodes.get(current.parentId);
            }
            return parts;
        }

        emit(type) {
            this.dispatchEvent(new Event(type));
        }
    }

