    async function saveNodeShopData(parentId, nodeId, currentData, overrides, overrideLang) {
        const { shop, tree, lang } = getUrlParams();

        const filterDef = currentData.filter_default === true || currentData.filter_default === 'y' ? 'y' : 'n';

        // Panel logic: own if BOTH sort and display_limit are truthy (not false/null/empty)
        let viewVal = (currentData.sort && currentData.display_limit) ? 'own' : 'default';

        const params = {
            action: 'editNodeShopData',
            node_type: currentData.node_type || 'p',
            filter_default: filterDef,
            target: currentData.target || '_self',
            lang: overrideLang || lang, shop, tree,
            node: nodeId,
            view: viewVal,
            parent: parentId,
            click_action: currentData.action || 'expand',
            element_hidden: currentData.hidden || 'n',
            displayShowAll: currentData.display_all || 'n',
            showAllIs: currentData.display_all_type || 'products_list',
            expand: currentData.expand || 'n',
            node_gfx: currentData.node_gfx || 'n',
            node_navigation_gfx: getNavGfxCache()[nodeId] || (currentData.gfx_nav ? 'y' : 'n'),
            gfx_active_type: currentData.gfx_active_type || 'img',
            gfx_inactive_type: currentData.gfx_inactive_type || 'img',
            gfx_omo_type: currentData.gfx_omo_type || 'img',
            name: currentData.name || '',
            text_d_headline_name: currentData.headline_name ? 'o' : 'd',
            headline_name: currentData.headline_name || '',
            link: currentData.link || '',
        };

        // Apply overrides
        for (const [key, value] of Object.entries(overrides)) {
            params[key] = value;
        }

        return ajaxPost(params);
    }

    async function saveNodeSEOData(nodeId, currentData, seoOverrides, overrideLang) {
        const { shop, tree, lang } = getUrlParams();

        // Derive meta_default: y if title+desc empty, n otherwise
        const hasCustomMeta = (currentData.meta_title && currentData.meta_title.trim()) ||
            (currentData.meta_description && currentData.meta_description.trim());
        const metaDefault = hasCustomMeta ? 'n' : 'y';

        const params = {
            action: 'editNodeSEOData',
            node: nodeId,
            lang: overrideLang || lang, shop, tree,
            meta_default: metaDefault,
            meta_title: currentData.meta_title || '',
            meta_desc: currentData.meta_description || '',
            meta_keywords: currentData.meta_keywords || '',
            meta_index: currentData.meta_robots_index || 'default',
            meta_follow: currentData.meta_robots_follow || 'default',
            canonical_to_parent: currentData.canonical_to_parent || 'n',
            own_url_default: currentData.own_url_default || 'y',
            own_url: currentData.own_url || '',
        };

        // Apply overrides
        for (const [key, value] of Object.entries(seoOverrides)) {
            params[key] = value;
        }

        // If meta_default = y → clear custom meta fields
        if (params.meta_default === 'y') {
            params.meta_title = '';
            params.meta_desc = '';
            params.meta_keywords = '';
        }

        return ajaxPost(params);
    }

    async function getNodeRedirects(nodeId) {
        const resp = await fetch('/panel/ajax/product-edit.php?action=getRedirectsTabToplayer', {
            method: 'POST',
            credentials: 'same-origin',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: `type=menu&id=${nodeId}&singleWindowView=getRedirectsList&callback=bulk`,
        });
        const data = await resp.json();
        if (data.errno) return [];
        const parser = new DOMParser();
        const doc = parser.parseFromString(data.value || '', 'text/html');
        const checkboxes = doc.querySelectorAll('input[type="checkbox"][name^="remove-redirect_"]');
        const redirects = [];
        for (const cb of checkboxes) {
            const key = cb.name.replace('remove-redirect_', '');
            redirects.push({ key, slug: cb.value });
        }
        return redirects;
    }

    async function removeAllNodeRedirects(nodeId, redirects) {
        if (!redirects || redirects.length === 0) return { status: 'ok' };
        const parts = redirects.map(r => `url[${r.key}][]=${encodeURIComponent('/' + r.slug)}`);
        const body = parts.join('&');
        const resp = await fetch(`/panel/ajax/product-edit.php?action=removeRedirects&id=${nodeId}&type=menu`, {
            method: 'POST',
            credentials: 'same-origin',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body,
        });
        return resp.json();
    }

