    async function removeAllNodeGfx(nodeId, target) {
        const slots = target === 'menu' ? ['inactive', 'omo', 'active'] : ['nav'];
        const versions = ['', 'desktop', 'tablet', 'mobile'];
        for (const slot of slots) {
            for (const ver of versions) {
                await removeNodeGfx(nodeId, slot, ver);
                await sleep(50);
            }
        }
    }

    async function setNodeFilters(nodeId, filterSort, pricestep, pricestepnet, extraOpts) {
        var { shop, tree, lang } = getUrlParams();
        // Panel expects LI-element IDs: filter_{shop}_active_sort[{filterId}]
        var prefixedSort = filterSort.split(',')
            .map(function(id) { return 'filter_' + shop + '_active_sort[' + id.trim() + ']'; })
            .join(',');
        var bodyParts = [
            'action=setNodeFilters',
            'node=' + encodeURIComponent(nodeId),
            'tree=' + encodeURIComponent(tree),
            'lang=' + encodeURIComponent(lang),
            'shop=' + encodeURIComponent(shop),
            'filter_sort=' + encodeURIComponent(prefixedSort),
            'filter_pricestep=' + encodeURIComponent(pricestep || '10'),
            'filter_pricestepnet=' + encodeURIComponent(pricestepnet || '10'),
        ];
        if (extraOpts) {
            // filter_display[key]=value
            if (extraOpts.filter_display) {
                for (var dk in extraOpts.filter_display) {
                    bodyParts.push('filter_display[' + encodeURIComponent(dk) + ']=' + encodeURIComponent(extraOpts.filter_display[dk]));
                }
            }
            // filter_default_enabled[key]=value
            if (extraOpts.filter_default_enabled) {
                for (var ek in extraOpts.filter_default_enabled) {
                    bodyParts.push('filter_default_enabled[' + encodeURIComponent(ek) + ']=' + encodeURIComponent(extraOpts.filter_default_enabled[ek]));
                }
            }
            // filter_alphabetical[key]=value
            if (extraOpts.filter_alphabetical) {
                for (var ak in extraOpts.filter_alphabetical) {
                    bodyParts.push('filter_alphabetical[' + encodeURIComponent(ak) + ']=' + encodeURIComponent(extraOpts.filter_alphabetical[ak]));
                }
            }
            // filter_pricerange[currency][minPrice|range|maxPrice]=value
            if (extraOpts.filter_pricerange) {
                for (var prCur in extraOpts.filter_pricerange) {
                    for (var prKey in extraOpts.filter_pricerange[prCur]) {
                        bodyParts.push('filter_pricerange[' + encodeURIComponent(prCur) + '][' + encodeURIComponent(prKey) + ']=' + encodeURIComponent(extraOpts.filter_pricerange[prCur][prKey]));
                    }
                }
            }
            // filter_pricerangenet[currency][minPrice|range|maxPrice]=value
            if (extraOpts.filter_pricerangenet) {
                for (var pnCur in extraOpts.filter_pricerangenet) {
                    for (var pnKey in extraOpts.filter_pricerangenet[pnCur]) {
                        bodyParts.push('filter_pricerangenet[' + encodeURIComponent(pnCur) + '][' + encodeURIComponent(pnKey) + ']=' + encodeURIComponent(extraOpts.filter_pricerangenet[pnCur][pnKey]));
                    }
                }
            }
            // filter_name[key]=value
            if (extraOpts.filter_name) {
                for (var nk in extraOpts.filter_name) {
                    bodyParts.push('filter_name[' + encodeURIComponent(nk) + ']=' + encodeURIComponent(extraOpts.filter_name[nk]));
                }
            }
        }
        var bodyStr = bodyParts.join('&');
        var resp = await fetch('/panel/ajax/navigation.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            credentials: 'same-origin',
            body: bodyStr,
        });
        var text = await resp.text();
        try {
            return JSON.parse(text);
        } catch (e) {
            if (text.trimStart().startsWith('<')) {
                throw new Error('Sesja wygasła — odśwież stronę i zaloguj się ponownie');
            }
            throw new Error('Nieprawidłowa odpowiedź serwera');
        }
    }

