    function getMenuHeading(iframeDoc) {
        const h1 = iframeDoc.querySelector('h1');
        return h1 ? h1.textContent.trim() : '';
    }

    function getShopDomain(iframeDoc) {
        const heading = getMenuHeading(iframeDoc);
        const match = heading.match(/dla\s+(\S+)/);
        return match ? match[1] : location.hostname;
    }

    // =========================================================================
    // SHOP / MENU SWITCHER — fetch navigation.php list and parse available shops+menus
    // =========================================================================
    let _shopsMenusCache = null;

    async function fetchShopsAndMenus() {
        // Return cached data if available
        if (_shopsMenusCache) return _shopsMenusCache;

        // Try sessionStorage first
        const cached = sessionStorage.getItem('idm_shops_menus');
        if (cached) {
            try {
                _shopsMenusCache = JSON.parse(cached);
                return _shopsMenusCache;
            } catch (_) { /* ignore */ }
        }

        try {
            const resp = await fetch('/panel/navigation.php', { credentials: 'same-origin' });
            if (!resp.ok) return null;
            const html = await resp.text();
            const parser = new DOMParser();
            const doc = parser.parseFromString(html, 'text/html');
            const rows = doc.querySelectorAll('table tr');
            const shops = [];

            for (const row of rows) {
                const cells = row.querySelectorAll('td');
                if (cells.length < 2) continue;
                const domain = cells[0].textContent.trim();
                if (!domain) continue;

                const menuLinks = cells[1].querySelectorAll('a[href*="action=menuTree"]');
                const menus = [];
                for (const link of menuLinks) {
                    const href = link.getAttribute('href') || '';
                    const shopMatch = href.match(/[?&]shop=(\d+)/);
                    const treeMatch = href.match(/[?&]tree=(\d+)/);
                    if (shopMatch && treeMatch) {
                        menus.push({
                            name: link.textContent.trim(),
                            shop: shopMatch[1],
                            tree: treeMatch[1],
                        });
                    }
                }
                if (menus.length > 0) {
                    shops.push({ domain, shop: menus[0].shop, menus });
                }
            }

            _shopsMenusCache = shops;
            sessionStorage.setItem('idm_shops_menus', JSON.stringify(shops));
            return shops;
        } catch (_) {
            return null;
        }
    }

    // =========================================================================
    // TREE VIEWS — saved filtered views of selected nodes
    // =========================================================================

    function getViewsStorageKey() {
        const { shop, tree } = getUrlParams();
        return 'idm_tree_views_' + shop + '_' + tree;
    }

    function loadSavedViews() {
        try {
            const raw = localStorage.getItem(getViewsStorageKey());
            return raw ? JSON.parse(raw) : [];
        } catch (_) { return []; }
    }

    function saveSavedViews(views) {
        try {
            localStorage.setItem(getViewsStorageKey(), JSON.stringify(views));
        } catch (_) { /* quota exceeded */ }
    }

    function createView(store, name) {
        if (!name || store.selected.size === 0) return null;
        const nodes = [];
        for (const id of store.selected) {
            const path = store.getNodePath(id);
            nodes.push({ id, path: path.join('/') });
        }
        const view = {
            id: 'v_' + Date.now(),
            name: name.trim(),
            createdAt: Date.now(),
            nodes,
        };
        const views = loadSavedViews();
        views.push(view);
        saveSavedViews(views);
        return view;
    }

    function deleteView(viewId) {
        const views = loadSavedViews().filter(v => v.id !== viewId);
        saveSavedViews(views);
    }

    function resolveViewNodeIds(store, view) {
        // Returns Set of node IDs in the view, resolved by ID first, then path fallback
        const result = new Set();
        if (!view || !view.nodes) return result;
        for (const entry of view.nodes) {
            // Try by ID first
            if (store.nodes.has(entry.id)) {
                result.add(entry.id);
                continue;
            }
            // Fallback: match by path
            if (entry.path) {
                for (const [id, node] of store.nodes) {
                    const nodePath = store.getNodePath(id).join('/');
                    if (nodePath === entry.path) {
                        result.add(id);
                        break;
                    }
                }
            }
        }
        return result;
    }

    function getViewAncestorIds(store, nodeIds) {
        // Collect all ancestor IDs for context display
        const ancestors = new Set();
        for (const id of nodeIds) {
            let current = store.nodes.get(id);
            while (current && current.parentId !== '0') {
                if (ancestors.has(current.parentId)) break;
                ancestors.add(current.parentId);
                current = store.nodes.get(current.parentId);
            }
        }
        return ancestors;
    }

    function refreshViewsDropdown(store) {
        const list = document.getElementById('idm-views-list');
        const label = document.getElementById('idm-view-label');
        if (!list) return;

        const views = loadSavedViews();
        const activeId = store.activeView ? store.activeView.id : null;

        let html = `<div class="idm-dropdown__item${!activeId ? ' idm-dropdown__item--active' : ''}" data-action="clear-view">
            <span class="material-symbols-outlined">visibility</span> Wszystko
        </div>`;

        if (views.length > 0) {
            html += '<div class="idm-dropdown__divider"></div>';
            for (const v of views) {
                const isActive = v.id === activeId;
                html += `<div class="idm-dropdown__item idm-view-item${isActive ? ' idm-dropdown__item--active' : ''}" data-action="load-view" data-view-id="${v.id}">
                    <span class="material-symbols-outlined">bookmark</span>
                    <span class="idm-view-item__name">${v.name}</span>
                    <span class="idm-view-item__count">${v.nodes.length}</span>
                    <button class="idm-view-item__delete" data-action="delete-view" data-view-id="${v.id}" title="Usuń widok">
                        <span class="material-symbols-outlined">close</span>
                    </button>
                </div>`;
            }
        }

        html += '<div class="idm-dropdown__divider"></div>';
        html += `<div class="idm-dropdown__item${store.selected.size === 0 ? ' idm-dropdown__item--disabled' : ''}" data-action="save-view">
            <span class="material-symbols-outlined">bookmark_add</span> Zapisz zaznaczone jako widok…
        </div>`;

        list.innerHTML = html;
        if (label) {
            label.textContent = activeId && store.activeView ? store.activeView.name : 'Wszystko';
        }
        const dropdown = document.getElementById('idm-views-dropdown');
        if (dropdown) {
            dropdown.classList.toggle('idm-views--active', !!activeId);
        }
    }

